#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Writes crates/gostr/src/isprint.rs from Go's src/strconv/isprint.go (the tables strconv.IsPrint uses).

    python3 scripts/gen_isprint.py "$(go env GOROOT)/src/strconv/isprint.go" > crates/gostr/src/isprint.rs
"""
import re
import sys

src = open(sys.argv[1]).read()
ver = sys.argv[2] if len(sys.argv) > 2 else "go1.27.2"
out = [
    "// SPDX-License-Identifier: BSD-3-Clause",
    "// Generated by scripts/gen_isprint.py from Go's src/strconv/isprint.go (%s). Do not edit." % ver,
    "// Derived from Go's src/strconv/isprint.go: Copyright 2013 The Go Authors. All rights reserved. Under the",
    "// BSD-3-Clause licence in rust/LICENSE-GO.",
    "",
]
for name, rtype in [("isPrint16", "u16"), ("isNotPrint16", "u16"), ("isPrint32", "u32"), ("isNotPrint32", "u16"),
                    ("isGraphic", "u16")]:
    m = re.search(r"var %s = \[\]uint(16|32)\{(.*?)\n\}" % name, src, re.S)
    assert m, name
    body = re.sub(r"//[^\n]*", "", m.group(2))
    vals = [int(x, 16) for x in re.findall(r"0x[0-9a-fA-F]+", body)]
    rust = re.sub(r"(?<!^)([A-Z0-9]+)", lambda k: "_" + k.group(1), name).upper()
    out.append("#[rustfmt::skip]")
    out.append("pub(crate) static %s: [%s; %d] = [" % (rust, rtype, len(vals)))
    for i in range(0, len(vals), 12):
        out.append("    " + " ".join("0x%04x," % v for v in vals[i:i + 12]))
    out.append("];")
    out.append("")
sys.stdout.write("\n".join(out))
